def find_identity():
    for i in range(-10, 11):
        identity = True
        for j in range(-10, 11):
            if (i * j) % 2 != 0:
                identity = False
                break
        if identity:
            return i
print(find_identity())

import math
primes = [True] * 201
primes[0] = primes[1] = False
for i in range(2, int(math.sqrt(200)) + 1):
    if primes[i]:
        for j in range(i*i, 201, i):
            primes[j] = False
perfect_squares = [i**2 for i in range(1, int(math.sqrt(200)) + 1)]
sum_primes = 0
for i in range(100, 201):
    if primes[i] and (i-1) in perfect_squares or (i-2) in perfect_squares:
        sum_primes += i
print(sum_primes)
